import { Group, Mesh, BoxGeometry, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string[]} [textContent]
 * @property {Object} [intent]
 * @property {Object} [intent.visualSpec]
 * @property {string} [meshUrl]
 * @property {string} [depthMapUrl]
 * @property {string} [imageUrl]
 * @property {Object[]} [cinematicPrimitives]
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {any} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * Create a gradient material for the cell surfaces.
 * @param {string} startHex
 * @param {string} endHex
 * @returns {MeshStandardNodeMaterial}
 */
function createCellMaterial(startHex, endHex) {
  const mat = new MeshStandardNodeMaterial();
  const startCol = new Color(startHex);
  const endCol = new Color(endHex);
  const startNode = vec3(startCol.r, startCol.g, startCol.b);
  const endNode = vec3(endCol.r, endCol.g, endCol.b);
  const uvNode = uv();
  // diagonal factor (approx 135°)
  const factor = uvNode.x.add(uvNode.y).div(2);
  mat.colorNode = mix(startNode, endNode, factor);
  mat.metalness = 0.45;
  mat.roughness = 0.5;
  mat.clearcoat = 0.2;
  mat.transparent = true;
  mat.opacity = 0;
  return mat;
}

/**
 * Create the thin emissive tick bar.
 * @returns {Mesh}
 */
function createTickBarMaterial() {
  const mat = new MeshBasicNodeMaterial();
  const accent = new Color('#ff2a38');
  mat.colorNode = vec3(accent.r, accent.g, accent.b);
  mat.transparent = true;
  mat.opacity = 0;
  return mat;
}

/**
 * Build a single cell (slab + tick + texts).
 */
function buildCell(params) {
  const {
    width,
    height,
    valueText,
    labelText,
    valueFontSize,
    labelFontSize,
    isDominant,
    padding = 0.5,
  } = params;

  const cellGroup = new Group();

  // slab
  const geometry = new BoxGeometry(width, height, 0.06);
  const material = createCellMaterial('#101017', '#1a1a22');
  const slab = new Mesh(geometry, material);
  slab.position.set(0, 0, 0);
  cellGroup.add(slab);

  // tick bar
  const tickGeo = new BoxGeometry(0.4, 0.05, 0.02);
  const tickMat = createTickBarMaterial();
  const tick = new Mesh(tickGeo, tickMat);
  const tickX = -width / 2 + padding + 0.2; // half tick width
  const tickY = height / 2 - padding - 0.025; // half tick height
  tick.position.set(tickX, tickY, 0.04);
  cellGroup.add(tick);

  // value text
  if (valueText) {
    const valueObj = ctx.fontAtlas.createText(valueText, {
      fontSize: valueFontSize,
      color: '#e8ecf2',
      align: 'left',
    });
    const valueX = -width / 2 + padding;
    const valueY = height / 2 - padding - valueFontSize * 0.01; // rough estimate
    valueObj.position.set(valueX, valueY, 0.07);
    cellGroup.add(valueObj);
  }

  // label text
  if (labelText) {
    const labelObj = ctx.fontAtlas.createText(labelText, {
      fontSize: labelFontSize,
      color: '#e8ecf2',
      align: 'left',
    });
    const labelX = -width / 2 + padding;
    const labelY = -height / 2 + padding + labelFontSize * 0.01; // bottom-left inside padding
    labelObj.position.set(labelX, labelY, 0.07);
    cellGroup.add(labelObj);
  }

  // expose materials for cleanup & animation
  cellGroup.userData._materials = [material, tickMat];
  cellGroup.userData._geometries = [geometry, tickGeo];
  return cellGroup;
}

/**
 * Main export.
 */
export default function createNode(config, ctx) {
  const root = new Group();

  // ----- Backdrop plane (stage) -----
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial();
  const bgStart = new Color('#101017');
  const bgEnd = new Color('#1a1a22');
  const startNode = vec3(bgStart.r, bgStart.g, bgStart.b);
  const endNode = vec3(bgEnd.r, bgEnd.g, bgEnd.b);
  const uvNode = uv();
  const factorNode = uvNode.y; // vertical gradient
  backdropMat.colorNode = mix(startNode, endNode, factorNode);
  backdropMat.metalness = 0;
  backdropMat.roughness = 1;
  backdropMat.transparent = true;
  backdropMat.opacity = 1;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ----- Header caption -----
  const header = ctx.fontAtlas.createText('ATELIER METRICS / Q2 2026', {
    fontSize: 18,
    color: '#ff2a38',
    align: 'left',
  });
  header.position.set(-2.75, 2.25, 0.01);
  root.add(header);

  // ----- Grid cells -----
  const cells = [];

  // Dominant cell (left column)
  const dominant = buildCell({
    width: 3.25,
    height: 3.5,
    valueText: '0.002 mm',
    labelText: 'Case tolerance, CNC pass',
    valueFontSize: 124,
    labelFontSize: 18,
    isDominant: true,
  });
  dominant.position.set(-1.125, 0, 0);
  root.add(dominant);
  cells.push(dominant);

  // Top-right secondary cell
  const topRight = buildCell({
    width: 2.0,
    height: 1.625,
    valueText: '38 h',
    labelText: 'Power reserve, NA-01',
    valueFontSize: 68,
    labelFontSize: 18,
    isDominant: false,
  });
  topRight.position.set(1.75, 0.8125, 0);
  root.add(topRight);
  cells.push(topRight);

  // Bottom-right secondary cell
  const bottomRight = buildCell({
    width: 2.0,
    height: 1.625,
    valueText: '214',
    labelText: 'Components per calibre',
    valueFontSize: 68,
    labelFontSize: 18,
    isDominant: false,
  });
  bottomRight.position.set(1.75, -0.8125, 0);
  root.add(bottomRight);
  cells.push(bottomRight);

  // ----- Entrance animation (stagger-cards, fade-up) -----
  const timelines = [];
  cells.forEach((cell, idx) => {
    // start displaced & invisible
    cell.position.y += 0.2;
    cell.traverse((obj) => {
      if (obj.isMesh && obj.material) {
        obj.material.transparent = true;
        obj.material.opacity = 0;
      }
    });

    const tl = gsap.timeline({ paused: true, delay: idx * 0.08 });
    tl.to(
      cell.position,
      {
        y: '-=0.2',
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      0
    );
    cell.traverse((obj) => {
      if (obj.isMesh && obj.material) {
        tl.to(
          obj.material,
          {
            opacity: 1,
            duration: 0.5,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          },
          0
        );
      }
    });
    tl.play();
    timelines.push(tl);
  });

  // ----- Cleanup ----------
  root.userData.cleanup = () => {
    // dispose geometries & materials
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      }
    });
    // dispose custom stored resources
    cells.forEach((c) => {
      if (c.userData._geometries) c.userData._geometries.forEach((g) => g.dispose && g.dispose());
      if (c.userData._materials) c.userData._materials.forEach((m) => m.dispose && m.dispose());
    });
    // kill GSAP timelines
    timelines.forEach((tl) => tl.kill());
    // kill any remaining tweens on the root
    gsap.killTweensOf(root);
  };

  // No cinematic primitives to apply per config

  return root;
}
